import os

from flask import Flask, jsonify


def create_upstream(flag_path):
    app = Flask("upstream")
    hits = {"count": 0}

    @app.get("/data")
    def data():
        hits["count"] += 1
        if os.path.exists(flag_path):
            return jsonify(error="upstream_broken"), 500
        return jsonify(ok=True)

    # Test hook: total number of times upstream was actually reached.
    app.extensions["hit_count"] = hits
    return app


